#include <algorithm>
#include <cstddef>
#include <iostream>
#include <print>
#include <string>
#include <utility>
#include <vector>

class Series {
public:
    Series(std::string name, std::size_t size) : name_(std::move(name)), size_(size), values_(new double[size]()) {}
    ~Series() {
        delete[] values_;
    }

    void set(std::size_t i, double v) {
        values_[i] = v;
    }

    const std::string &name() const {
        return name_;
    }

    double mean() const {
        double sum = 0;
        for (std::size_t i = 0; i < size_; ++i) {
            sum += values_[i];
        }
        return size_ ? sum / static_cast<double>(size_) : 0;
    }

private:
    std::string name_;
    std::size_t size_;
    double *values_;
};

int main() {
    std::vector<Series> all;
    std::string command, name;
    while (std::cin >> command >> name) {
        if (command == "series") {
            std::size_t n;
            std::cin >> n;
            Series s(name, n);
            for (std::size_t i = 0; i < n; ++i) {
                double v;
                std::cin >> v;
                s.set(i, v);
            }
            all.push_back(s);
        } else {
            for (const Series &s : all) {
                if (s.name() == name) {
                    std::println("{}: {:.2f}", name, s.mean());
                }
            }
        }
    }
    return 0;
}

