int main() {
    // Напишите решение здесь.
    return 0;
}

additionalExercises.referenceSolution:
#include <algorithm>
#include <cstddef>
#include <iostream>
#include <map>
#include <print>
#include <string>
#include <utility>

class Ring {
public:
    explicit Ring(std::size_t capacity) : capacity_(capacity), data_(new int[capacity]()) {}
    Ring(const Ring &other)
        : capacity_(other.capacity_), head_(other.head_), size_(other.size_), data_(new int[other.capacity_]) {
        std::copy_n(other.data_, capacity_, data_);
    }
    Ring &operator=(const Ring &other) {
        Ring copy(other);
        std::swap(capacity_, copy.capacity_);
        std::swap(head_, copy.head_);
        std::swap(size_, copy.size_);
        std::swap(data_, copy.data_);
        return *this;
    }
    ~Ring() {
        delete[] data_;
    }

    bool push(int v, int &evicted) {
        if (size_ < capacity_) {
            data_[(head_ + size_) % capacity_] = v;
            ++size_;
            return false;
        }
        evicted = data_[head_];
        data_[head_] = v;
        head_ = (head_ + 1) % capacity_;
        return true;
    }

    bool empty() const {
        return size_ == 0;
    }

    int pop() {
        const int v = data_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return v;
    }

    std::string text() const {
        std::string s;
        for (std::size_t i = 0; i < size_; ++i) {
            s += (i ? " " : "") + std::to_string(data_[(head_ + i) % capacity_]);
        }
        return s.empty() ? "пусто" : s;
    }

private:
    std::size_t capacity_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
    int *data_;
};

int main() {
    std::map<std::string, Ring> rings;
    std::string command, x;
    while (std::cin >> command >> x) {
        if (command == "make") {
            std::size_t c;
            std::cin >> c;
            rings.insert_or_assign(x, Ring(c));
        } else if (command == "push") {
            int v, evicted = 0;
            std::cin >> v;
            if (rings.at(x).push(v, evicted)) {
                std::println("{}: вытеснено {}", x, evicted);
            }
        } else if (command == "pop") {
            Ring &r = rings.at(x);
            if (r.empty()) {
                std::println("{}: пусто", x);
            } else {
                std::println("{}", r.pop());
            }
        } else if (command == "copy") {
            std::string from;
            std::cin >> from;
            rings.insert_or_assign(x, rings.at(from));
        } else {
            std::println("{}: {}", x, rings.at(x).text());
        }
    }
    return 0;
}

